		string string = OptionType.COLOR_TYPE.convertObjectToString(c);
		assertEquals(c.getRGB(),
			((Color) OptionType.COLOR_TYPE.convertStringToObject(string)).getRGB());
	}

	/* @Test */
	public void testFontConversion() {
