			this.b = b;
		}

		/* @Override */
		public int hashCode() {
			int prime = 31;
			int result = 1;
			result = prime * result + a;
			result = prime * result + ((b == null) ? 0 : b.hashCode());
			return result;
		}

		/* @Override */
		public bool equals(object obj) {
			if (this == obj) {
				return true;
			}
			if (obj == null) {
				return false;
			}
			if (getClass() != obj.GetType()) {
				return false;
			}
			MyCustomOption other = (MyCustomOption) obj;
			if (a != other.a) {
				return false;
			}
			if (b == null) {
				if (other.b != null) {
					return false;
				}
			}
			else if (!b.equals(other.b)) {
				return false;
			}
			return true;
		}

		/* @Override */
		public void readState(GProperties properties) {
			a = properties.getInt("a", 0);
			b = properties.getString("b", null);
		}

		/* @Override */
		public void writeState(GProperties properties) {
			properties.putInt("a", a);
			properties.putString("b", b);
		}

	}
